const playwright = require('playwright');
const fs = require('fs');

async function exploreAntigravity() {
  console.log('Connecting to browser...');
  const browser = await playwright.chromium.connectOverCDP('http://localhost:9222');
  const context = browser.contexts()[0] || await browser.newContext();
  const page = await context.newPage();

  const findings = {
    mainPage: {},
    links: [],
    errors: []
  };

  try {
    console.log('Navigating to https://antigravity.google/...');
    await page.goto('https://antigravity.google/', { 
      waitUntil: 'networkidle',
      timeout: 30000 
    });

    // Wait a bit for any dynamic content
    await page.waitForTimeout(2000);

    // Get page title
    findings.mainPage.title = await page.title();
    console.log('Page title:', findings.mainPage.title);

    // Get page URL (in case of redirects)
    findings.mainPage.url = page.url();
    console.log('Final URL:', findings.mainPage.url);

    // Extract all text content
    findings.mainPage.bodyText = await page.evaluate(() => {
      return document.body.innerText;
    });

    // Get all headings
    findings.mainPage.headings = await page.evaluate(() => {
      const headings = [];
      const elements = document.querySelectorAll('h1, h2, h3, h4, h5, h6');
      elements.forEach(el => {
        headings.push({
          tag: el.tagName,
          text: el.innerText.trim()
        });
      });
      return headings;
    });

    // Get meta description
    findings.mainPage.metaDescription = await page.evaluate(() => {
      const meta = document.querySelector('meta[name="description"]');
      return meta ? meta.getAttribute('content') : null;
    });

    // Find all links on the page
    const allLinks = await page.evaluate(() => {
      const links = [];
      document.querySelectorAll('a[href]').forEach(a => {
        links.push({
          text: a.innerText.trim(),
          href: a.href,
          title: a.title || ''
        });
      });
      return links;
    });

    console.log(`Found ${allLinks.length} links on main page`);

    // Filter for important-looking links (docs, API, features, about, etc.)
    const importantKeywords = [
      'doc', 'api', 'feature', 'guide', 'about', 'getting started',
      'reference', 'tutorial', 'integration', 'overview', 'introduction'
    ];

    const importantLinks = allLinks.filter(link => {
      const combinedText = (link.text + ' ' + link.href + ' ' + link.title).toLowerCase();
      return importantKeywords.some(keyword => combinedText.includes(keyword));
    });

    console.log(`Found ${importantLinks.length} important links`);

    // Visit important links (limit to 10 to avoid too long execution)
    const linksToVisit = importantLinks.slice(0, 10);

    for (const link of linksToVisit) {
      try {
        console.log(`Visiting: ${link.href}`);
        await page.goto(link.href, { 
          waitUntil: 'networkidle',
          timeout: 20000 
        });
        await page.waitForTimeout(1500);

        const linkData = {
          originalText: link.text,
          url: page.url(),
          title: await page.title(),
          bodyText: await page.evaluate(() => document.body.innerText),
          headings: await page.evaluate(() => {
            const headings = [];
            const elements = document.querySelectorAll('h1, h2, h3, h4, h5, h6');
            elements.forEach(el => {
              headings.push({
                tag: el.tagName,
                text: el.innerText.trim()
              });
            });
            return headings;
          })
        };

        findings.links.push(linkData);
        console.log(`  Title: ${linkData.title}`);
      } catch (error) {
        console.error(`Error visiting ${link.href}:`, error.message);
        findings.errors.push({
          link: link.href,
          error: error.message
        });
      }
    }

    // Take a screenshot of the main page
    await page.goto('https://antigravity.google/', { 
      waitUntil: 'networkidle',
      timeout: 30000 
    });
    await page.waitForTimeout(1000);
    await page.screenshot({ 
      path: '/job/tmp/antigravity-screenshot.png',
      fullPage: true 
    });
    console.log('Screenshot saved');

  } catch (error) {
    console.error('Main error:', error);
    findings.errors.push({
      context: 'main',
      error: error.message,
      stack: error.stack
    });
  } finally {
    await page.close();
    await browser.close();
  }

  // Save findings to JSON for processing
  fs.writeFileSync('/job/tmp/findings.json', JSON.stringify(findings, null, 2));
  console.log('Findings saved to /job/tmp/findings.json');
}

exploreAntigravity().catch(console.error);

const playwright = require('playwright');
const fs = require('fs');

async function exploreDetailed() {
  console.log('Connecting to browser...');
  const browser = await playwright.chromium.connectOverCDP('http://localhost:9222');
  const context = browser.contexts()[0] || await browser.newContext();
  const page = await context.newPage();

  const findings = {};

  // List of URLs/paths to explore
  const pagesToExplore = [
    { name: 'home', url: 'https://antigravity.google/' },
    { name: 'docs', url: 'https://antigravity.google/docs' },
    { name: 'api', url: 'https://antigravity.google/api' },
    { name: 'guide', url: 'https://antigravity.google/guide' },
    { name: 'getting-started', url: 'https://antigravity.google/getting-started' },
    { name: 'features', url: 'https://antigravity.google/features' },
    { name: 'download', url: 'https://antigravity.google/download' },
    { name: 'pricing', url: 'https://antigravity.google/pricing' },
    { name: 'blog', url: 'https://antigravity.google/blog' }
  ];

  for (const pageInfo of pagesToExplore) {
    try {
      console.log(`\n--- Exploring: ${pageInfo.name} ---`);
      console.log(`URL: ${pageInfo.url}`);

      const response = await page.goto(pageInfo.url, { 
        waitUntil: 'networkidle',
        timeout: 20000 
      });

      if (!response || response.status() === 404) {
        console.log(`  ⚠ Page not found (404)`);
        continue;
      }

      await page.waitForTimeout(2000);

      const pageData = {
        url: page.url(),
        status: response.status(),
        title: await page.title(),
        bodyText: '',
        headings: [],
        links: [],
        codeBlocks: [],
        apiEndpoints: []
      };

      // Extract body text
      try {
        pageData.bodyText = await page.evaluate(() => {
          const body = document.body.innerText;
          return body.substring(0, 10000); // Limit to 10K chars
        });
      } catch (e) {
        console.log(`  ⚠ Could not extract body text: ${e.message}`);
      }

      // Get headings
      try {
        pageData.headings = await page.evaluate(() => {
          const headings = [];
          document.querySelectorAll('h1, h2, h3, h4, h5, h6').forEach(el => {
            headings.push({
              tag: el.tagName,
              text: el.innerText.trim().substring(0, 200)
            });
          });
          return headings;
        });
      } catch (e) {
        console.log(`  ⚠ Could not extract headings: ${e.message}`);
      }

      // Get all links
      try {
        pageData.links = await page.evaluate(() => {
          const links = [];
          document.querySelectorAll('a[href]').forEach(a => {
            const href = a.href;
            const text = a.innerText.trim().substring(0, 100);
            if (href && !links.find(l => l.href === href)) {
              links.push({ text, href });
            }
          });
          return links.slice(0, 50); // Limit to 50 links
        });
      } catch (e) {
        console.log(`  ⚠ Could not extract links: ${e.message}`);
      }

      // Look for code examples
      try {
        pageData.codeBlocks = await page.evaluate(() => {
          const blocks = [];
          document.querySelectorAll('code, pre, .code-block, .code-example').forEach(el => {
            const text = el.innerText.trim();
            if (text.length > 10 && text.length < 2000) {
              blocks.push(text);
            }
          });
          return blocks.slice(0, 10);
        });
      } catch (e) {
        console.log(`  ⚠ Could not extract code blocks: ${e.message}`);
      }

      // Look for API-related content
      try {
        pageData.apiEndpoints = await page.evaluate(() => {
          const text = document.body.innerText;
          const endpoints = [];
          // Look for common API patterns
          const patterns = [
            /\/api\/[a-z0-9\-\/]+/gi,
            /https?:\/\/[^\s]+\/api\/[a-z0-9\-\/]+/gi,
            /POST|GET|PUT|DELETE|PATCH[\s]+\/[a-z0-9\-\/]+/gi
          ];
          patterns.forEach(pattern => {
            const matches = text.match(pattern);
            if (matches) {
              endpoints.push(...matches);
            }
          });
          return [...new Set(endpoints)].slice(0, 20);
        });
      } catch (e) {
        console.log(`  ⚠ Could not extract API endpoints: ${e.message}`);
      }

      findings[pageInfo.name] = pageData;
      console.log(`  ✓ Title: ${pageData.title}`);
      console.log(`  ✓ Body length: ${pageData.bodyText.length} chars`);
      console.log(`  ✓ Headings: ${pageData.headings.length}`);
      console.log(`  ✓ Links: ${pageData.links.length}`);
      console.log(`  ✓ Code blocks: ${pageData.codeBlocks.length}`);

    } catch (error) {
      console.error(`  ✗ Error: ${error.message}`);
      findings[pageInfo.name] = {
        error: error.message,
        url: pageInfo.url
      };
    }
  }

  await page.close();
  await browser.close();

  fs.writeFileSync('/job/tmp/detailed-findings.json', JSON.stringify(findings, null, 2));
  console.log('\n✓ Detailed findings saved to /job/tmp/detailed-findings.json');
}

