const playwright = require('playwright');
const fs = require('fs');

async function exploreDocs() {
  console.log('Connecting to browser...');
  const browser = await playwright.chromium.connectOverCDP('http://localhost:9222');
  const context = browser.contexts()[0] || await browser.newContext();
  const page = await context.newPage();

  const findings = {};

  // Key documentation pages
  const docPages = [
    'agent',
    'models',
    'agent-modes-settings',
    'rules-workflows',
    'skills',
    'task-groups',
    'browser-subagent',
    'mcp',
    'artifacts',
    'task-list',
    'editor',
    'tab',
    'command',
    'agent-manager',
    'workspaces',
    'conversation-view',
    'browser',
    'settings'
  ];

  for (const docName of docPages) {
    try {
      const url = `https://antigravity.google/docs/${docName}`;
      console.log(`\n--- ${docName} ---`);

      const response = await page.goto(url, { 
        waitUntil: 'networkidle',
        timeout: 20000 
      });

      if (!response || response.status() === 404) {
        console.log(`  ⚠ Not found`);
        continue;
      }

      await page.waitForTimeout(1500);

      const bodyText = await page.evaluate(() => {
        const main = document.querySelector('main') || document.body;
        return main.innerText.substring(0, 15000);
      });

      findings[docName] = {
        url: page.url(),
        content: bodyText.trim()
      };

      console.log(`  ✓ Captured ${bodyText.length} chars`);

    } catch (error) {
      console.error(`  ✗ ${error.message}`);
      findings[docName] = { error: error.message };
    }
  }

  await page.close();
  await browser.close();

  fs.writeFileSync('/job/tmp/doc-pages.json', JSON.stringify(findings, null, 2));
  console.log('\n✓ Documentation findings saved');
}

exploreDocs().catch(console.error);
